INSERT INTO nginx_ip_stat (
    source_id, bucket_time, client_ip, request_count,
    sum_request_time_ms, max_request_time_ms, slow_count, status_5xx, create_time
) VALUES (
    #{row.sourceId}, #{row.bucketTime}, #{row.clientIp}, #{row.requestCount},
    #{row.sumRequestTimeMs}, #{row.maxRequestTimeMs}, #{row.slowCount}, #{row.status5xx}, #{row.createTime}
)

mapper.select:
SELECT client_ip AS "clientIp", SUM(request_count) AS "requestCount", SUM(status_5xx) AS "status5xx", SUM(slow_count) AS "slowCount", MAX(max_request_time_ms) AS "maxRequestTimeMs", ROUND(SUM(sum_request_time_ms) * 1.0 / NULLIF(SUM(request_count), 0), 2) AS "avgRequestTimeMs" FROM nginx_ip_stat WHERE bucket_time >= #{startTime} AND bucket_time < #{endTime} AND source_id IN #{sid}
AND client_ip LIKE '%' || #{keyword} || '%'
GROUP BY client_ip
ORDER BY ROUND(SUM(sum_request_time_ms) * 1.0 / NULLIF(SUM(request_count), 0), 2) DESC ORDER BY MAX(max_request_time_ms) DESC ORDER BY SUM(request_count) DESC
LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*) FROM (
    SELECT client_ip
    FROM nginx_ip_stat
    WHERE bucket_time >= #{startTime}
      AND bucket_time < #{endTime}
      AND source_id IN
      #{sid}

          AND client_ip LIKE '%' || #{keyword} || '%'


    GROUP BY client_ip
) t

SELECT client_ip AS "clientIp", '__IP_SUMMARY__' AS "uri", '-' AS "method", SUM(request_count) AS "requestCount", SUM(slow_count) AS "slowCount", MAX(max_request_time_ms) AS "maxRequestTimeMs", ROUND(SUM(sum_request_time_ms) * 1.0 / NULLIF(SUM(request_count), 0), 2) AS "avgRequestTimeMs" FROM nginx_ip_stat WHERE bucket_time >= #{startTime} AND bucket_time < #{endTime} AND source_id IN #{sid}
AND client_ip LIKE '%' || #{clientIp} || '%'
GROUP BY client_ip
ORDER BY ROUND(SUM(sum_request_time_ms) * 1.0 / NULLIF(SUM(request_count), 0), 2) DESC ORDER BY MAX(max_request_time_ms) DESC ORDER BY SUM(request_count) DESC
LIMIT #{pageSize} OFFSET #{offset}

